<?php
declare(strict_types=1);require_once __DIR__.'/config.php';require_once __DIR__.'/lib/audit.php';if(empty($_SESSION['user_id'])){header('Location: /login.php');exit;}if(empty($_SESSION['csrf_token']))$_SESSION['csrf_token']=bin2hex(random_bytes(32));if(!defined('SLUG_MAX_LEN'))define('SLUG_MAX_LEN',30);
function clicuha_translit(string $v):string{$m=['а'=>'a','б'=>'b','в'=>'v','г'=>'h','ґ'=>'g','д'=>'d','е'=>'e','є'=>'ye','ж'=>'zh','з'=>'z','и'=>'y','і'=>'i','ї'=>'yi','й'=>'y','к'=>'k','л'=>'l','м'=>'m','н'=>'n','о'=>'o','п'=>'p','р'=>'r','с'=>'s','т'=>'t','у'=>'u','ф'=>'f','х'=>'h','ц'=>'ts','ч'=>'ch','ш'=>'sh','щ'=>'sch','ю'=>'yu','я'=>'ya','ь'=>'','ъ'=>'','’'=>'','\''=>'','ы'=>'y','э'=>'e','ё'=>'yo'];return strtr(mb_strtolower($v,'UTF-8'),$m);}function clicuha_slug(string $v):string{$v=clicuha_translit(trim($v));if(function_exists('iconv')){$c=@iconv('UTF-8','ASCII//TRANSLIT//IGNORE',$v);if($c!==false)$v=strtolower($c);}$v=preg_replace('/[^a-z0-9]+/','-',$v)??'';return substr(trim(preg_replace('/-+/','-',$v)??'','-'),0,SLUG_MAX_LEN);}function clicuha_unique_slug(PDO $pdo,string $base):string{if($base==='')return '';$slug=$base;$i=1;while(true){$s=$pdo->prepare('SELECT COUNT(*) FROM nicknames WHERE slug=:slug');$s->execute([':slug'=>$slug]);if((int)$s->fetchColumn()===0)return $slug;$i++;$suffix='-'.$i;$slug=rtrim(substr($base,0,max(1,SLUG_MAX_LEN-strlen($suffix))),'-').$suffix;}}
$errors=[];$title='';$slugInput='';$desc='';$isAnonymous=0;$created=isset($_GET['created']);
if($_SERVER['REQUEST_METHOD']==='POST'){if(!hash_equals($_SESSION['csrf_token'],(string)($_POST['csrf_token']??''))){http_response_code(403);exit('Invalid CSRF token');}$title=trim($_POST['title']??'');$slugInput=trim($_POST['slug']??'');$desc=trim($_POST['description']??'');$isAnonymous=isset($_POST['is_anonymous'])?1:0;$publish=($_POST['save_mode']??'publish')==='publish'?1:0;if($title==='')$errors[]='Назва Clicuha обовʼязкова.';$slug=clicuha_slug($slugInput!==''?$slugInput:$title);if($slug!=='')$slug=clicuha_unique_slug($pdo,$slug);if(!$errors){$stmt=$pdo->prepare('INSERT INTO nicknames (title,slug,description,is_anonymous,is_published,user_id) VALUES (:title,:slug,:description,:anon,:published,:uid)');$uid=(int)$_SESSION['user_id'];$stmt->execute([':title'=>$title,':slug'=>$slug?:null,':description'=>$desc?:null,':anon'=>$isAnonymous,':published'=>$publish,':uid'=>$uid]);$id=(int)$pdo->lastInsertId();clicuha_audit($pdo,$uid,$publish?'clicuha_create':'clicuha_create_cabinet','clicuha_id='.$id.'; title='.$title);header('Location: /add_bootstrap.php?created='.($publish?'published':'cabinet'));exit;}}
?><!doctype html><html lang="<?=h($lang)?>"><head><meta charset="utf-8"><title>New Clicuha</title><meta name="viewport" content="width=device-width,initial-scale=1"><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link rel="stylesheet" href="/assets/css/sema.css?v=124"></head><body class="bg-light"><?php require __DIR__.'/partials/navbar.php';?><div class="container py-4"><div class="row justify-content-center"><div class="col-md-8 col-lg-6"><div class="card shadow-sm"><div class="card-body"><h1 class="h4 mb-3">New Clicuha</h1><?php if($errors):?><div class="alert alert-danger"><?php foreach($errors as $e):?><div><?=h($e)?></div><?php endforeach;?></div><?php endif;?><form method="post"><input type="hidden" name="csrf_token" value="<?=h($_SESSION['csrf_token'])?>"><div class="mb-3"><label class="form-label">Clicuha*</label><input class="form-control" name="title" id="title" value="<?=h($title)?>" required></div><div class="mb-3"><label class="form-label">Slug (optional)</label><input class="form-control" name="slug" id="slug" value="<?=h($slugInput)?>"></div><div class="mb-3"><label class="form-label">Who is… (optional)</label><textarea class="form-control" name="description" rows="3"><?=h($desc)?></textarea></div><div class="form-check mb-3"><input class="form-check-input" type="checkbox" name="is_anonymous" id="is_anonymous" <?=$isAnonymous?'checked':''?>><label class="form-check-label" for="is_anonymous">Анонімно</label></div><div class="d-flex flex-wrap gap-2"><button name="save_mode" value="publish" class="clic-btn clic-btn-yes">Опублікувати</button><button name="save_mode" value="cabinet" class="btn btn-outline-secondary">Зберегти в кабінеті</button></div></form></div></div></div></div></div><?php if($created):?><div class="modal fade" id="successModal" tabindex="-1"><div class="modal-dialog modal-dialog-centered"><div class="modal-content"><div class="modal-header"><h5 class="modal-title"><?=$created==='cabinet'?'Клікуху збережено в кабінеті':'Клікуху опубліковано'?></h5><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><?=$created==='cabinet'?'Клікуха поки не відображається в Галереї.':'Клікуха доступна в Галереї.'?></div><div class="modal-footer"><a href="/my_nicknames.php" class="btn btn-primary">Мої клікухи</a></div></div></div></div><?php endif;?><script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"></script><script>document.addEventListener('DOMContentLoaded',()=>{<?php if($created):?>new bootstrap.Modal(document.getElementById('successModal')).show();<?php endif;?>});</script></body></html>